questions.solution:
type PaymentStatus = "pending" | "paid" | "refunded";

const LEGACY: Readonly<Record<number, PaymentStatus>> = { 0: "pending", 1: "paid", 2: "refunded" };
const ALL: readonly PaymentStatus[] = ["pending", "paid", "refunded"];

function readStatus(stored: unknown): PaymentStatus | "invalid" {
  if (typeof stored === "number") return LEGACY[stored] ?? "invalid";
  for (const status of ALL) {
    if (status === stored) return status;
  }
  return "invalid";
}

console.log([0, 2, "paid", 5, "Paid"].map(readStatus).join(" "));

