type PaymentStatus = "pending" | "paid" | "refunded";

function nextAction(status: PaymentStatus): string {
  switch (status) {
    case "pending":
      return "wait";
    case "paid":
      return "send receipt";
    case "refunded":
      return "close";
  }
}

const statuses: PaymentStatus[] = ["pending", "paid", "refunded"];
console.log(statuses.map(nextAction).join(" | "));

