const METHODS = ["card", "transfer", "ussd"] as const;
type PaymentMethod = (typeof METHODS)[number];

function isPaymentMethod(value: unknown): value is PaymentMethod {
  return METHODS.some((method) => method === value);
}

const input: unknown[] = ["ussd", "cash", "card", 3];
const valid: PaymentMethod[] = input.filter(isPaymentMethod);
console.log(valid);
